package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.lang.reflect.Proxy;
/** Restore outcomes include a real failed preference commit; only synthetic data is allowed. */
public final class Beta998BundleNativeTest extends Instrumentation {
 int checks;void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 Context failed(Context c){return new ContextWrapper(c){@Override public SharedPreferences getSharedPreferences(String name,int mode){SharedPreferences p=super.getSharedPreferences(name,mode);if(!name.equals("beta_experience_v1"))return p;return (SharedPreferences)Proxy.newProxyInstance(SharedPreferences.class.getClassLoader(),new Class[]{SharedPreferences.class},(proxy,method,args)->{if(!method.getName().equals("edit"))return method.invoke(p,args);SharedPreferences.Editor editor=p.edit();return Proxy.newProxyInstance(SharedPreferences.Editor.class.getClassLoader(),new Class[]{SharedPreferences.Editor.class},(self,action,values)->{if(action.getName().equals("commit"))return false;Object result=action.invoke(editor,values);return result instanceof SharedPreferences.Editor?self:result;});});}};}
 @Override public void onStart(){Bundle result=new Bundle();int code=0;Context c=getTargetContext();JSONObject original=null;String account=null;try{
  check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter.trial")&&TrialDemo.active(c),"Owned synthetic beta");account=SubscriptionStore.accountKey(c);original=BetaBundle.collect(c,account,true,true);long xp=BetaGrowthStore.load(c,account).getLong("total");JSONObject personal=original.getJSONObject("personal");
  BetaIdentity.save(c,"교체 전 임시 이름");BetaPreferences.prefs(c).edit().putString("preset","simple").commit();FunStore.tone(c,"off");
  String outcome=BetaBundle.restore(c,account,original,true,true);check(outcome.contains("완료")||outcome.contains("applied"),"Completed outcome");
  check(BetaIdentity.name(c).equals(ProfileCard.nickname(personal.getString("name"))),"Actual identity restored");check(BetaPreferences.preset(c).equals(personal.getString("preset")),"Actual preset restored");check(FunStore.tone(c).equals(personal.getString("tone")),"Actual OFF/tone record restored");check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Full roundtrip no extra XP");
  for(int i=0;i<3;i++)BetaBundle.restore(c,account,original,true,true);check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Repeated full restore idempotent");
  String partial=BetaBundle.restore(failed(c),account,original,true,true);check(partial.contains("오류")||partial.contains("failed"),"Real settings commit failure reports partial failure");check(BetaGrowthStore.load(c,account).getLong("total")==xp,"Partial settings failure preserves committed growth");
  check(!BetaBundle.collect(c,account,false,true).has("growth"),"Settings-only export excludes growth");check(!BetaBundle.collect(c,account,true,false).has("settings"),"Growth-only export excludes settings");
  JSONObject auth=new JSONObject(original.toString());auth.getJSONObject("settings").getJSONObject("sections").put("authentication",new JSONObject());boolean denied=false;try{BetaBundle.preview(c,account,auth,true,true);}catch(Exception expected){denied=true;}check(denied,"Authentication injected into settings refused");
  String raw=c.getSharedPreferences("codex_meter_updates_v1",0).getString("releases","[]"),etag=UpdatePreferences.etag(c);String large=" ".repeat(600000)+"[]";
  try{UpdatePreferences.saveSuccess(c,large,"");check(c.getSharedPreferences("codex_meter_updates_v1",0).getString("releases","").length()==large.length(),"Metadata cache above old512KiB accepted");boolean refused=false;try{UpdatePreferences.saveSuccess(c," ".repeat(2*1024*1024+1),"");}catch(IllegalArgumentException expected){refused=true;}check(refused,"Metadata cache remains bounded at2MiB");}finally{UpdatePreferences.saveSuccess(c,raw,etag);}
  java.lang.reflect.Field limit=ReleaseUpdateClient.class.getDeclaredField("MAX_RESPONSE_BYTES");limit.setAccessible(true);check(limit.getInt(null)==2*1024*1024,"Actual network response bound2MiB");
  java.lang.reflect.Method read=ReleaseUpdateClient.class.getDeclaredMethod("read",java.io.InputStream.class,int.class);read.setAccessible(true);check(((String)read.invoke(null,new java.io.ByteArrayInputStream(large.getBytes(java.nio.charset.StandardCharsets.UTF_8)),limit.getInt(null))).length()==large.length(),"Actual response reader accepts larger bounded metadata");
  result.putString("stream","Beta998 bundle: "+checks+" checks passed; actual restore/commit-failure/section selection; synthetic only.\n");code=-1;
 }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));}finally{if(original!=null)try{BetaBundle.restore(c,account,original,true,true);}catch(Exception e){code=0;result.putString("stream",result.getString("stream","")+"Cleanup failed");}}finish(code,result);}
}
